#[test]
fn system_nano_time_monotonic() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    let r1 = call_native(
        &shared,
        &mut thread,
        "java/lang/System",
        "nanoTime",
        "()J",
        &[],
    )
    .unwrap();
    let r2 = call_native(
        &shared,
        &mut thread,
        "java/lang/System",
        "nanoTime",
        "()J",
        &[],
    )
    .unwrap();
    let t1 = match r1 {
        Some(Value::Long(v)) => v,
        _ => panic!("Expected long"),
    };
    let t2 = match r2 {
        Some(Value::Long(v)) => v,
        _ => panic!("Expected long"),
    };
    assert!(t2 >= t1, "nanoTime should be monotonic");
}

