#[test]
fn character_is_digit() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    // '5' = 0x35 = 53
    let r = call_native(
        &shared,
        &mut thread,
        "java/lang/Character",
        "isDigit",
        "(C)Z",
        &[Value::Int('5' as i32)],
    )
    .unwrap();
    assert_eq!(r, Some(Value::Int(1)));

    // 'a' is not a digit
    let r = call_native(
        &shared,
        &mut thread,
        "java/lang/Character",
        "isDigit",
        "(C)Z",
        &[Value::Int('a' as i32)],
    )
    .unwrap();
    assert_eq!(r, Some(Value::Int(0)));
}

#[test]
fn character_is_letter() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    let r = call_native(
        &shared,
        &mut thread,
        "java/lang/Character",
        "isLetter",
        "(C)Z",
        &[Value::Int('Z' as i32)],
    )
    .unwrap();
    assert_eq!(r, Some(Value::Int(1)));

    let r = call_native(
        &shared,
        &mut thread,
        "java/lang/Character",
        "isLetter",
        "(C)Z",
        &[Value::Int('3' as i32)],
    )
    .unwrap();
    assert_eq!(r, Some(Value::Int(0)));
}

#[test]
fn character_case_conversion() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    let r = call_native(
        &shared,
        &mut thread,
        "java/lang/Character",
        "toUpperCase",
        "(C)C",
        &[Value::Int('a' as i32)],
    )
    .unwrap();
    assert_eq!(r, Some(Value::Int('A' as i32)));

    let r = call_native(
        &shared,
        &mut thread,
        "java/lang/Character",
        "toLowerCase",
        "(C)C",
        &[Value::Int('Z' as i32)],
    )
    .unwrap();
    assert_eq!(r, Some(Value::Int('z' as i32)));
}

