#[test]
fn arraylist_basic() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    // Create ArrayList (2 fields: elementData, size)
    let list = shared.mem.heap.alloc_object(ClassId::new(0), 2);
    call_native(
        &shared,
        &mut thread,
        "java/util/ArrayList",
        "<init>",
        "()V",
        &[Value::Object(Some(list))],
    )
    .unwrap();

    // isEmpty → true
    let empty = call_native(
        &shared,
        &mut thread,
        "java/util/ArrayList",
        "isEmpty",
        "()Z",
        &[Value::Object(Some(list))],
    )
    .unwrap();
    assert_eq!(empty, Some(Value::Int(1)));

    // size → 0
    let size = call_native(
        &shared,
        &mut thread,
        "java/util/ArrayList",
        "size",
        "()I",
        &[Value::Object(Some(list))],
    )
    .unwrap();
    assert_eq!(size, Some(Value::Int(0)));

    // add("hello")
    let hello = create_java_string(&shared, "hello");
    call_native(
        &shared,
        &mut thread,
        "java/util/ArrayList",
        "add",
        "(Ljava/lang/Object;)Z",
        &[Value::Object(Some(list)), Value::Object(Some(hello))],
    )
    .unwrap();

    // add("world")
    let world = create_java_string(&shared, "world");
    call_native(
        &shared,
        &mut thread,
        "java/util/ArrayList",
        "add",
        "(Ljava/lang/Object;)Z",
        &[Value::Object(Some(list)), Value::Object(Some(world))],
    )
    .unwrap();

    // size → 2
    let size = call_native(
        &shared,
        &mut thread,
        "java/util/ArrayList",
        "size",
        "()I",
        &[Value::Object(Some(list))],
    )
    .unwrap();
    assert_eq!(size, Some(Value::Int(2)));

    // isEmpty → false
    let empty = call_native(
        &shared,
        &mut thread,
        "java/util/ArrayList",
        "isEmpty",
        "()Z",
        &[Value::Object(Some(list))],
    )
    .unwrap();
    assert_eq!(empty, Some(Value::Int(0)));

    // get(0) → "hello"
    let elem = call_native(
        &shared,
        &mut thread,
        "java/util/ArrayList",
        "get",
        "(I)Ljava/lang/Object;",
        &[Value::Object(Some(list)), Value::Int(0)],
    )
    .unwrap();
    if let Some(Value::Object(Some(s))) = elem {
        assert_eq!(
            read_java_string(&shared.mem.heap, s),
            Some("hello".to_string())
        );
    } else {
        panic!("expected String, got {elem:?}");
    }

    // get(1) → "world"
    let elem = call_native(
        &shared,
        &mut thread,
        "java/util/ArrayList",
        "get",
        "(I)Ljava/lang/Object;",
        &[Value::Object(Some(list)), Value::Int(1)],
    )
    .unwrap();
    if let Some(Value::Object(Some(s))) = elem {
        assert_eq!(
            read_java_string(&shared.mem.heap, s),
            Some("world".to_string())
        );
    } else {
        panic!("expected String, got {elem:?}");
    }
}

