#[test]
fn objects_equals_and_hash() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    // null == null → true
    let r = call_native(
        &shared,
        &mut thread,
        "java/util/Objects",
        "equals",
        "(Ljava/lang/Object;Ljava/lang/Object;)Z",
        &[Value::Object(None), Value::Object(None)],
    )
    .unwrap();
    assert_eq!(r, Some(Value::Int(1)));

    // same string → true
    let s1 = create_java_string(&shared, "abc");
    let s2 = create_java_string(&shared, "abc");
    let r = call_native(
        &shared,
        &mut thread,
        "java/util/Objects",
        "equals",
        "(Ljava/lang/Object;Ljava/lang/Object;)Z",
        &[Value::Object(Some(s1)), Value::Object(Some(s2))],
    )
    .unwrap();
    assert_eq!(r, Some(Value::Int(1)));

    // null vs non-null → false
    let r = call_native(
        &shared,
        &mut thread,
        "java/util/Objects",
        "equals",
        "(Ljava/lang/Object;Ljava/lang/Object;)Z",
        &[Value::Object(Some(s1)), Value::Object(None)],
    )
    .unwrap();
    assert_eq!(r, Some(Value::Int(0)));

    // hashCode(null) == 0
    let r = call_native(
        &shared,
        &mut thread,
        "java/util/Objects",
        "hashCode",
        "(Ljava/lang/Object;)I",
        &[Value::Object(None)],
    )
    .unwrap();
    assert_eq!(r, Some(Value::Int(0)));
}

