#[test]
fn optional_empty_and_of() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    // Optional.empty() → isPresent=false
    let empty = call_native(
        &shared,
        &mut thread,
        "java/util/Optional",
        "empty",
        "()Ljava/util/Optional;",
        &[],
    )
    .unwrap();
    let empty_ref = match empty {
        Some(Value::Object(Some(r))) => r,
        _ => panic!("expected Optional object"),
    };
    let r = call_native(
        &shared,
        &mut thread,
        "java/util/Optional",
        "isPresent",
        "()Z",
        &[Value::Object(Some(empty_ref))],
    )
    .unwrap();
    assert_eq!(r, Some(Value::Int(0)));

    let r = call_native(
        &shared,
        &mut thread,
        "java/util/Optional",
        "isEmpty",
        "()Z",
        &[Value::Object(Some(empty_ref))],
    )
    .unwrap();
    assert_eq!(r, Some(Value::Int(1)));

    // Optional.of(value) → get returns value
    let s = create_java_string(&shared, "hello");
    let opt = call_native(
        &shared,
        &mut thread,
        "java/util/Optional",
        "of",
        "(Ljava/lang/Object;)Ljava/util/Optional;",
        &[Value::Object(Some(s))],
    )
    .unwrap();
    let opt_ref = match opt {
        Some(Value::Object(Some(r))) => r,
        _ => panic!("expected Optional object"),
    };
    let r = call_native(
        &shared,
        &mut thread,
        "java/util/Optional",
        "isPresent",
        "()Z",
        &[Value::Object(Some(opt_ref))],
    )
    .unwrap();
    assert_eq!(r, Some(Value::Int(1)));

    let r = call_native(
        &shared,
        &mut thread,
        "java/util/Optional",
        "get",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(opt_ref))],
    )
    .unwrap();
    assert_eq!(r, Some(Value::Object(Some(s))));
}

