/// Helper: create a StringBuilder, init it, append a string, return the sb ref
fn make_sb(shared: &Arc<SharedVm>, thread: &mut JvmThread, initial: &str) -> ObjectRef {
    let sb = shared.mem.heap.alloc_object(ClassId::new(0), 2);
    call_native(
        shared,
        thread,
        "java/lang/StringBuilder",
        "<init>",
        "()V",
        &[Value::Object(Some(sb))],
    )
    .unwrap();
    if !initial.is_empty() {
        let s = create_java_string(shared, initial);
        call_native(
            shared,
            thread,
            "java/lang/StringBuilder",
            "append",
            "(Ljava/lang/String;)Ljava/lang/StringBuilder;",
            &[Value::Object(Some(sb)), Value::Object(Some(s))],
        )
        .unwrap();
    }
    sb
}

fn sb_to_string(shared: &Arc<SharedVm>, thread: &mut JvmThread, sb: ObjectRef) -> String {
    let result = call_native(
        shared,
        thread,
        "java/lang/StringBuilder",
        "toString",
        "()Ljava/lang/String;",
        &[Value::Object(Some(sb))],
    )
    .unwrap()
    .unwrap();
    match result {
        Value::Object(Some(sr)) => read_java_string(&shared.mem.heap, sr).unwrap(),
        _ => panic!("expected string"),
    }
}

