// --- HashMap null-key tests ---

#[test]
fn hashmap_null_key_put_get() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");
    let map = shared.mem.heap.alloc_object(ClassId::new(0), 3);
    call_native(
        &shared,
        &mut thread,
        "java/util/HashMap",
        "<init>",
        "()V",
        &[Value::Object(Some(map))],
    )
    .unwrap();

    let val = create_java_string(&shared, "null_value");
    call_native(
        &shared,
        &mut thread,
        "java/util/HashMap",
        "put",
        "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;",
        &[
            Value::Object(Some(map)),
            Value::Object(None),
            Value::Object(Some(val)),
        ],
    )
    .unwrap();

    let got = call_native(
        &shared,
        &mut thread,
        "java/util/HashMap",
        "get",
        "(Ljava/lang/Object;)Ljava/lang/Object;",
        &[Value::Object(Some(map)), Value::Object(None)],
    )
    .unwrap()
    .unwrap();

    match got {
        Value::Object(Some(r)) => {
            assert_eq!(read_java_string(&shared.mem.heap, r).unwrap(), "null_value")
        }
        _ => panic!("expected string, got {:?}", got),
    }
}

#[test]
fn hashmap_null_key_overwrite() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");
    let map = shared.mem.heap.alloc_object(ClassId::new(0), 3);
    call_native(
        &shared,
        &mut thread,
        "java/util/HashMap",
        "<init>",
        "()V",
        &[Value::Object(Some(map))],
    )
    .unwrap();

    let a = create_java_string(&shared, "a");
    let b = create_java_string(&shared, "b");
    call_native(
        &shared,
        &mut thread,
        "java/util/HashMap",
        "put",
        "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;",
        &[
            Value::Object(Some(map)),
            Value::Object(None),
            Value::Object(Some(a)),
        ],
    )
    .unwrap();
    call_native(
        &shared,
        &mut thread,
        "java/util/HashMap",
        "put",
        "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;",
        &[
            Value::Object(Some(map)),
            Value::Object(None),
            Value::Object(Some(b)),
        ],
    )
    .unwrap();

    let got = call_native(
        &shared,
        &mut thread,
        "java/util/HashMap",
        "get",
        "(Ljava/lang/Object;)Ljava/lang/Object;",
        &[Value::Object(Some(map)), Value::Object(None)],
    )
    .unwrap()
    .unwrap();

    match got {
        Value::Object(Some(r)) => {
            assert_eq!(read_java_string(&shared.mem.heap, r).unwrap(), "b")
        }
        _ => panic!("expected string"),
    }

    // Size should be 1 (overwritten, not added)
    let size = call_native(
        &shared,
        &mut thread,
        "java/util/HashMap",
        "size",
        "()I",
        &[Value::Object(Some(map))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(size, Value::Int(1));
}

#[test]
fn hashmap_null_key_contains() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");
    let map = shared.mem.heap.alloc_object(ClassId::new(0), 3);
    call_native(
        &shared,
        &mut thread,
        "java/util/HashMap",
        "<init>",
        "()V",
        &[Value::Object(Some(map))],
    )
    .unwrap();

    // Not present yet
    let before = call_native(
        &shared,
        &mut thread,
        "java/util/HashMap",
        "containsKey",
        "(Ljava/lang/Object;)Z",
        &[Value::Object(Some(map)), Value::Object(None)],
    )
    .unwrap()
    .unwrap();
    assert_eq!(before, Value::Int(0));

    // Add null key
    let val = create_java_string(&shared, "x");
    call_native(
        &shared,
        &mut thread,
        "java/util/HashMap",
        "put",
        "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;",
        &[
            Value::Object(Some(map)),
            Value::Object(None),
            Value::Object(Some(val)),
        ],
    )
    .unwrap();

    let after = call_native(
        &shared,
        &mut thread,
        "java/util/HashMap",
        "containsKey",
        "(Ljava/lang/Object;)Z",
        &[Value::Object(Some(map)), Value::Object(None)],
    )
    .unwrap()
    .unwrap();
    assert_eq!(after, Value::Int(1));
}

