#[test]
fn math_floor_div_and_mod() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    // floorDiv(7, 2) = 3
    let r = call_native(
        &shared,
        &mut thread,
        "java/lang/Math",
        "floorDiv",
        "(II)I",
        &[Value::Int(7), Value::Int(2)],
    )
    .unwrap()
    .unwrap();
    assert_eq!(r, Value::Int(3));

    // floorDiv(-7, 2) = -4 (rounds toward negative infinity)
    let r = call_native(
        &shared,
        &mut thread,
        "java/lang/Math",
        "floorDiv",
        "(II)I",
        &[Value::Int(-7), Value::Int(2)],
    )
    .unwrap()
    .unwrap();
    assert_eq!(r, Value::Int(-4));

    // floorDiv(7, -2) = -4
    let r = call_native(
        &shared,
        &mut thread,
        "java/lang/Math",
        "floorDiv",
        "(II)I",
        &[Value::Int(7), Value::Int(-2)],
    )
    .unwrap()
    .unwrap();
    assert_eq!(r, Value::Int(-4));

    // floorMod(7, 2) = 1
    let r = call_native(
        &shared,
        &mut thread,
        "java/lang/Math",
        "floorMod",
        "(II)I",
        &[Value::Int(7), Value::Int(2)],
    )
    .unwrap()
    .unwrap();
    assert_eq!(r, Value::Int(1));

    // floorMod(-7, 2) = 1 (always same sign as divisor)
    let r = call_native(
        &shared,
        &mut thread,
        "java/lang/Math",
        "floorMod",
        "(II)I",
        &[Value::Int(-7), Value::Int(2)],
    )
    .unwrap()
    .unwrap();
    assert_eq!(r, Value::Int(1));

    // Long variants
    let r = call_native(
        &shared,
        &mut thread,
        "java/lang/Math",
        "floorDiv",
        "(JJ)J",
        &[Value::Long(-7), Value::Long(2)],
    )
    .unwrap()
    .unwrap();
    assert_eq!(r, Value::Long(-4));

    let r = call_native(
        &shared,
        &mut thread,
        "java/lang/Math",
        "floorMod",
        "(JJ)J",
        &[Value::Long(-7), Value::Long(2)],
    )
    .unwrap()
    .unwrap();
    assert_eq!(r, Value::Long(1));
}

