#[test]
fn linked_list_add_and_get() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    let ll = shared.mem.heap.alloc_object(ClassId::new(0), 3);
    call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList",
        "<init>",
        "()V",
        &[Value::Object(Some(ll))],
    )
    .unwrap();

    // add elements
    for i in 0..5 {
        let s = {
            let mut ctx = NativeContextImpl {
                shared: &shared,
                thread: &mut thread,
            };
            ctx.create_string(&format!("item{i}"))
        };
        call_native(
            &shared,
            &mut thread,
            "java/util/LinkedList",
            "add",
            "(Ljava/lang/Object;)Z",
            &[Value::Object(Some(ll)), Value::Object(Some(s))],
        )
        .unwrap();
    }

    // size should be 5
    let r = call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList",
        "size",
        "()I",
        &[Value::Object(Some(ll))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(r, Value::Int(5));

    // get(0) = "item0"
    let r = call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList",
        "get",
        "(I)Ljava/lang/Object;",
        &[Value::Object(Some(ll)), Value::Int(0)],
    )
    .unwrap()
    .unwrap();
    match r {
        Value::Object(Some(sr)) => {
            assert_eq!(read_java_string(&shared.mem.heap, sr).unwrap(), "item0")
        }
        _ => panic!("expected string"),
    }

    // get(4) = "item4"
    let r = call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList",
        "get",
        "(I)Ljava/lang/Object;",
        &[Value::Object(Some(ll)), Value::Int(4)],
    )
    .unwrap()
    .unwrap();
    match r {
        Value::Object(Some(sr)) => {
            assert_eq!(read_java_string(&shared.mem.heap, sr).unwrap(), "item4")
        }
        _ => panic!("expected string"),
    }
}

