#[test]
fn linked_list_iterator() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    let ll = shared.mem.heap.alloc_object(ClassId::new(0), 3);
    call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList",
        "<init>",
        "()V",
        &[Value::Object(Some(ll))],
    )
    .unwrap();

    for i in 1..=3 {
        call_native(
            &shared,
            &mut thread,
            "java/util/LinkedList",
            "add",
            "(Ljava/lang/Object;)Z",
            &[Value::Object(Some(ll)), Value::Int(i)],
        )
        .unwrap();
    }

    let itr = call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList",
        "iterator",
        "()Ljava/util/Iterator;",
        &[Value::Object(Some(ll))],
    )
    .unwrap()
    .unwrap();
    let itr_obj = match itr {
        Value::Object(Some(obj)) => obj,
        _ => panic!("expected iterator"),
    };

    let mut sum = 0;
    for _ in 0..3 {
        let has = call_native(
            &shared,
            &mut thread,
            "java/util/LinkedList$Itr",
            "hasNext",
            "()Z",
            &[Value::Object(Some(itr_obj))],
        )
        .unwrap()
        .unwrap();
        assert_eq!(has, Value::Int(1));
        let v = call_native(
            &shared,
            &mut thread,
            "java/util/LinkedList$Itr",
            "next",
            "()Ljava/lang/Object;",
            &[Value::Object(Some(itr_obj))],
        )
        .unwrap()
        .unwrap();
        if let Value::Int(n) = v {
            sum += n;
        }
    }
    assert_eq!(sum, 6); // 1+2+3

    let has = call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList$Itr",
        "hasNext",
        "()Z",
        &[Value::Object(Some(itr_obj))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(has, Value::Int(0));
}

#[test]
fn linked_list_peek_and_poll() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    let ll = shared.mem.heap.alloc_object(ClassId::new(0), 3);
    call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList",
        "<init>",
        "()V",
        &[Value::Object(Some(ll))],
    )
    .unwrap();

    // peek on empty returns null
    let r = call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList",
        "peek",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(ll))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(r, Value::Object(None));

    // poll on empty returns null
    let r = call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList",
        "poll",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(ll))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(r, Value::Object(None));

    call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList",
        "add",
        "(Ljava/lang/Object;)Z",
        &[Value::Object(Some(ll)), Value::Int(10)],
    )
    .unwrap();
    call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList",
        "add",
        "(Ljava/lang/Object;)Z",
        &[Value::Object(Some(ll)), Value::Int(20)],
    )
    .unwrap();

    // peek returns 10 without removing
    let r = call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList",
        "peek",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(ll))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(r, Value::Int(10));

    // poll removes and returns 10
    let r = call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList",
        "poll",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(ll))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(r, Value::Int(10));

    // poll again returns 20
    let r = call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList",
        "poll",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(ll))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(r, Value::Int(20));

    // Now empty
    let r = call_native(
        &shared,
        &mut thread,
        "java/util/LinkedList",
        "size",
        "()I",
        &[Value::Object(Some(ll))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(r, Value::Int(0));
}

