#[test]
fn array_deque_add_first_last() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    let deque = shared.mem.heap.alloc_object(ClassId::new(0), 4);
    call_native(
        &shared,
        &mut thread,
        "java/util/ArrayDeque",
        "<init>",
        "()V",
        &[Value::Object(Some(deque))],
    )
    .unwrap();

    let s1 = {
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        ctx.create_string("B")
    };
    let s2 = {
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        ctx.create_string("A")
    };
    let s3 = {
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        ctx.create_string("C")
    };

    // Add B, then A at front, then C at back → [A, B, C]
    call_native(
        &shared,
        &mut thread,
        "java/util/ArrayDeque",
        "addLast",
        "(Ljava/lang/Object;)V",
        &[Value::Object(Some(deque)), Value::Object(Some(s1))],
    )
    .unwrap();
    call_native(
        &shared,
        &mut thread,
        "java/util/ArrayDeque",
        "addFirst",
        "(Ljava/lang/Object;)V",
        &[Value::Object(Some(deque)), Value::Object(Some(s2))],
    )
    .unwrap();
    call_native(
        &shared,
        &mut thread,
        "java/util/ArrayDeque",
        "addLast",
        "(Ljava/lang/Object;)V",
        &[Value::Object(Some(deque)), Value::Object(Some(s3))],
    )
    .unwrap();

    // peekFirst should be A
    let first = call_native(
        &shared,
        &mut thread,
        "java/util/ArrayDeque",
        "peekFirst",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(deque))],
    )
    .unwrap()
    .unwrap();
    let first_obj = match first {
        Value::Object(Some(r)) => r,
        _ => panic!("expected object"),
    };
    assert_eq!(
        read_java_string(&shared.mem.heap, first_obj),
        Some("A".to_string())
    );

    // peekLast should be C
    let last = call_native(
        &shared,
        &mut thread,
        "java/util/ArrayDeque",
        "peekLast",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(deque))],
    )
    .unwrap()
    .unwrap();
    let last_obj = match last {
        Value::Object(Some(r)) => r,
        _ => panic!("expected object"),
    };
    assert_eq!(
        read_java_string(&shared.mem.heap, last_obj),
        Some("C".to_string())
    );
}

