#[test]
fn stack_push_pop_peek() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    let stack = shared.mem.heap.alloc_object(ClassId::new(0), 2);
    call_native(
        &shared,
        &mut thread,
        "java/util/Stack",
        "<init>",
        "()V",
        &[Value::Object(Some(stack))],
    )
    .unwrap();

    // push returns the item
    let s1 = {
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        ctx.create_string("first")
    };
    let pushed = call_native(
        &shared,
        &mut thread,
        "java/util/Stack",
        "push",
        "(Ljava/lang/Object;)Ljava/lang/Object;",
        &[Value::Object(Some(stack)), Value::Object(Some(s1))],
    )
    .unwrap()
    .unwrap();
    match pushed {
        Value::Object(Some(_)) => {}
        _ => panic!("push should return the item"),
    };

    let s2 = {
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        ctx.create_string("second")
    };
    call_native(
        &shared,
        &mut thread,
        "java/util/Stack",
        "push",
        "(Ljava/lang/Object;)Ljava/lang/Object;",
        &[Value::Object(Some(stack)), Value::Object(Some(s2))],
    )
    .unwrap();

    // peek returns top without removing
    let pk = call_native(
        &shared,
        &mut thread,
        "java/util/Stack",
        "peek",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(stack))],
    )
    .unwrap()
    .unwrap();
    let pk_obj = match pk {
        Value::Object(Some(r)) => r,
        _ => panic!("expected object"),
    };
    assert_eq!(
        read_java_string(&shared.mem.heap, pk_obj),
        Some("second".to_string())
    );

    // pop returns top
    let popped = call_native(
        &shared,
        &mut thread,
        "java/util/Stack",
        "pop",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(stack))],
    )
    .unwrap()
    .unwrap();
    let popped_obj = match popped {
        Value::Object(Some(r)) => r,
        _ => panic!("expected object"),
    };
    assert_eq!(
        read_java_string(&shared.mem.heap, popped_obj),
        Some("second".to_string())
    );

    // Now top is "first"
    let pk2 = call_native(
        &shared,
        &mut thread,
        "java/util/Stack",
        "peek",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(stack))],
    )
    .unwrap()
    .unwrap();
    let pk2_obj = match pk2 {
        Value::Object(Some(r)) => r,
        _ => panic!("expected object"),
    };
    assert_eq!(
        read_java_string(&shared.mem.heap, pk2_obj),
        Some("first".to_string())
    );
}

#[test]
fn stack_search() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    let stack = shared.mem.heap.alloc_object(ClassId::new(0), 2);
    call_native(
        &shared,
        &mut thread,
        "java/util/Stack",
        "<init>",
        "()V",
        &[Value::Object(Some(stack))],
    )
    .unwrap();

    let s1 = {
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        ctx.create_string("A")
    };
    let s2 = {
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        ctx.create_string("B")
    };
    let s3 = {
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        ctx.create_string("C")
    };

    call_native(
        &shared,
        &mut thread,
        "java/util/Stack",
        "push",
        "(Ljava/lang/Object;)Ljava/lang/Object;",
        &[Value::Object(Some(stack)), Value::Object(Some(s1))],
    )
    .unwrap();
    call_native(
        &shared,
        &mut thread,
        "java/util/Stack",
        "push",
        "(Ljava/lang/Object;)Ljava/lang/Object;",
        &[Value::Object(Some(stack)), Value::Object(Some(s2))],
    )
    .unwrap();
    call_native(
        &shared,
        &mut thread,
        "java/util/Stack",
        "push",
        "(Ljava/lang/Object;)Ljava/lang/Object;",
        &[Value::Object(Some(stack)), Value::Object(Some(s3))],
    )
    .unwrap();

    // Stack: [A, B, C] — C is at top (distance 1)
    let search_c = {
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        ctx.create_string("C")
    };
    let pos = call_native(
        &shared,
        &mut thread,
        "java/util/Stack",
        "search",
        "(Ljava/lang/Object;)I",
        &[Value::Object(Some(stack)), Value::Object(Some(search_c))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(pos, Value::Int(1));

    let search_a = {
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        ctx.create_string("A")
    };
    let pos2 = call_native(
        &shared,
        &mut thread,
        "java/util/Stack",
        "search",
        "(Ljava/lang/Object;)I",
        &[Value::Object(Some(stack)), Value::Object(Some(search_a))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(pos2, Value::Int(3));

    let search_x = {
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        ctx.create_string("X")
    };
    let pos3 = call_native(
        &shared,
        &mut thread,
        "java/util/Stack",
        "search",
        "(Ljava/lang/Object;)I",
        &[Value::Object(Some(stack)), Value::Object(Some(search_x))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(pos3, Value::Int(-1));
}

