#[test]
fn tree_set_iterator() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    let ts = shared.mem.heap.alloc_object(ClassId::new(0), 3);
    call_native(
        &shared,
        &mut thread,
        "java/util/TreeSet",
        "<init>",
        "()V",
        &[Value::Object(Some(ts))],
    )
    .unwrap();

    for name in ["c", "a", "b"] {
        let s = {
            let mut ctx = NativeContextImpl {
                shared: &shared,
                thread: &mut thread,
            };
            ctx.create_string(name)
        };
        call_native(
            &shared,
            &mut thread,
            "java/util/TreeSet",
            "add",
            "(Ljava/lang/Object;)Z",
            &[Value::Object(Some(ts)), Value::Object(Some(s))],
        )
        .unwrap();
    }

    let itr = call_native(
        &shared,
        &mut thread,
        "java/util/TreeSet",
        "iterator",
        "()Ljava/util/Iterator;",
        &[Value::Object(Some(ts))],
    )
    .unwrap()
    .unwrap();
    let itr_obj = match itr {
        Value::Object(Some(r)) => r,
        _ => panic!("expected"),
    };

    let mut collected = Vec::new();
    loop {
        let has = call_native(
            &shared,
            &mut thread,
            "java/util/TreeSet$Itr",
            "hasNext",
            "()Z",
            &[Value::Object(Some(itr_obj))],
        )
        .unwrap()
        .unwrap();
        if has == Value::Int(0) {
            break;
        }
        let val = call_native(
            &shared,
            &mut thread,
            "java/util/TreeSet$Itr",
            "next",
            "()Ljava/lang/Object;",
            &[Value::Object(Some(itr_obj))],
        )
        .unwrap()
        .unwrap();
        if let Value::Object(Some(r)) = val {
            if let Some(s) = read_java_string(&shared.mem.heap, r) {
                collected.push(s);
            }
        }
    }
    assert_eq!(collected, vec!["a", "b", "c"]);
}

