#[test]
fn scanner_next_has_next() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    let input = {
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        ctx.create_string("hello world  foo")
    };
    let sc = shared.mem.heap.alloc_object(ClassId::new(0), 5);
    call_native(
        &shared,
        &mut thread,
        "java/util/Scanner",
        "<init>",
        "(Ljava/lang/String;)V",
        &[Value::Object(Some(sc)), Value::Object(Some(input))],
    )
    .unwrap();

    // hasNext
    let hn = call_native(
        &shared,
        &mut thread,
        "java/util/Scanner",
        "hasNext",
        "()Z",
        &[Value::Object(Some(sc))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(hn, Value::Int(1));

    // next -> "hello"
    let t1 = call_native(
        &shared,
        &mut thread,
        "java/util/Scanner",
        "next",
        "()Ljava/lang/String;",
        &[Value::Object(Some(sc))],
    )
    .unwrap()
    .unwrap();
    let s1 = match t1 {
        Value::Object(Some(r)) => read_java_string(&shared.mem.heap, r),
        _ => None,
    };
    assert_eq!(s1, Some("hello".to_string()));

    // next -> "world"
    let t2 = call_native(
        &shared,
        &mut thread,
        "java/util/Scanner",
        "next",
        "()Ljava/lang/String;",
        &[Value::Object(Some(sc))],
    )
    .unwrap()
    .unwrap();
    let s2 = match t2 {
        Value::Object(Some(r)) => read_java_string(&shared.mem.heap, r),
        _ => None,
    };
    assert_eq!(s2, Some("world".to_string()));

    // next -> "foo"
    let t3 = call_native(
        &shared,
        &mut thread,
        "java/util/Scanner",
        "next",
        "()Ljava/lang/String;",
        &[Value::Object(Some(sc))],
    )
    .unwrap()
    .unwrap();
    let s3 = match t3 {
        Value::Object(Some(r)) => read_java_string(&shared.mem.heap, r),
        _ => None,
    };
    assert_eq!(s3, Some("foo".to_string()));

    // hasNext -> false
    let hn2 = call_native(
        &shared,
        &mut thread,
        "java/util/Scanner",
        "hasNext",
        "()Z",
        &[Value::Object(Some(sc))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(hn2, Value::Int(0));
}

