#[test]
fn byte_buffer_bulk_put_get() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    let bb = call_native(
        &shared,
        &mut thread,
        "java/nio/ByteBuffer",
        "allocate",
        "(I)Ljava/nio/ByteBuffer;",
        &[Value::Int(8)],
    )
    .unwrap()
    .unwrap();
    let bb_ref = match bb {
        Value::Object(Some(o)) => o,
        _ => panic!("expected object"),
    };

    // Create source byte array [100, 101, 102]
    let src = shared
        .mem
        .heap
        .alloc_array(ClassId::new(0), ArrayElementType::Byte, 3);
    let _ = shared.mem.heap.set_array_element(src, 0, Value::Int(100));
    let _ = shared.mem.heap.set_array_element(src, 1, Value::Int(101));
    let _ = shared.mem.heap.set_array_element(src, 2, Value::Int(102));

    // Bulk put
    call_native(
        &shared,
        &mut thread,
        "java/nio/ByteBuffer",
        "put",
        "([BII)Ljava/nio/ByteBuffer;",
        &[
            Value::Object(Some(bb_ref)),
            Value::Object(Some(src)),
            Value::Int(0),
            Value::Int(3),
        ],
    )
    .unwrap();

    let pos = call_native(
        &shared,
        &mut thread,
        "java/nio/ByteBuffer",
        "position",
        "()I",
        &[Value::Object(Some(bb_ref))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(pos, Value::Int(3));

    // Flip, bulk get into destination
    call_native(
        &shared,
        &mut thread,
        "java/nio/ByteBuffer",
        "flip",
        "()Ljava/nio/Buffer;",
        &[Value::Object(Some(bb_ref))],
    )
    .unwrap();

    let dst = shared
        .mem
        .heap
        .alloc_array(ClassId::new(0), ArrayElementType::Byte, 3);
    call_native(
        &shared,
        &mut thread,
        "java/nio/ByteBuffer",
        "get",
        "([BII)Ljava/nio/ByteBuffer;",
        &[
            Value::Object(Some(bb_ref)),
            Value::Object(Some(dst)),
            Value::Int(0),
            Value::Int(3),
        ],
    )
    .unwrap();

    assert_eq!(
        shared.mem.heap.get_array_element(dst, 0).unwrap(),
        Value::Int(100)
    );
    assert_eq!(
        shared.mem.heap.get_array_element(dst, 1).unwrap(),
        Value::Int(101)
    );
    assert_eq!(
        shared.mem.heap.get_array_element(dst, 2).unwrap(),
        Value::Int(102)
    );
}

#[test]
fn byte_buffer_put_bytebuffer() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    // Source ByteBuffer with [1, 2, 3]
    let src = call_native(
        &shared,
        &mut thread,
        "java/nio/ByteBuffer",
        "allocate",
        "(I)Ljava/nio/ByteBuffer;",
        &[Value::Int(4)],
    )
    .unwrap()
    .unwrap();
    let src_ref = match src {
        Value::Object(Some(o)) => o,
        _ => panic!("expected object"),
    };
    for i in 1..=3 {
        call_native(
            &shared,
            &mut thread,
            "java/nio/ByteBuffer",
            "put",
            "(B)Ljava/nio/ByteBuffer;",
            &[Value::Object(Some(src_ref)), Value::Int(i)],
        )
        .unwrap();
    }
    call_native(
        &shared,
        &mut thread,
        "java/nio/ByteBuffer",
        "flip",
        "()Ljava/nio/Buffer;",
        &[Value::Object(Some(src_ref))],
    )
    .unwrap();

    // Destination ByteBuffer
    let dst = call_native(
        &shared,
        &mut thread,
        "java/nio/ByteBuffer",
        "allocate",
        "(I)Ljava/nio/ByteBuffer;",
        &[Value::Int(8)],
    )
    .unwrap()
    .unwrap();
    let dst_ref = match dst {
        Value::Object(Some(o)) => o,
        _ => panic!("expected object"),
    };

    call_native(
        &shared,
        &mut thread,
        "java/nio/ByteBuffer",
        "put",
        "(Ljava/nio/ByteBuffer;)Ljava/nio/ByteBuffer;",
        &[Value::Object(Some(dst_ref)), Value::Object(Some(src_ref))],
    )
    .unwrap();

    // dst position should be 3
    let pos = call_native(
        &shared,
        &mut thread,
        "java/nio/ByteBuffer",
        "position",
        "()I",
        &[Value::Object(Some(dst_ref))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(pos, Value::Int(3));

    // Flip dst and read back
    call_native(
        &shared,
        &mut thread,
        "java/nio/ByteBuffer",
        "flip",
        "()Ljava/nio/Buffer;",
        &[Value::Object(Some(dst_ref))],
    )
    .unwrap();
    let v0 = call_native(
        &shared,
        &mut thread,
        "java/nio/ByteBuffer",
        "get",
        "()B",
        &[Value::Object(Some(dst_ref))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(v0, Value::Int(1));
    let v1 = call_native(
        &shared,
        &mut thread,
        "java/nio/ByteBuffer",
        "get",
        "()B",
        &[Value::Object(Some(dst_ref))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(v1, Value::Int(2));
    let v2 = call_native(
        &shared,
        &mut thread,
        "java/nio/ByteBuffer",
        "get",
        "()B",
        &[Value::Object(Some(dst_ref))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(v2, Value::Int(3));
}

