#[test]
fn reentrant_lock_basic_lock_unlock() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    let lock = alloc_receiver(
        &shared,
        &mut thread,
        "java/util/concurrent/locks/ReentrantLock",
        3,
    );
    call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/locks/ReentrantLock",
        "<init>",
        "()V",
        &[Value::Object(Some(lock))],
    )
    .unwrap();

    // Lock
    call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/locks/ReentrantLock",
        "lock",
        "()V",
        &[Value::Object(Some(lock))],
    )
    .unwrap();

    let locked = call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/locks/ReentrantLock",
        "isLocked",
        "()Z",
        &[Value::Object(Some(lock))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(locked, Value::Int(1));

    let held = call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/locks/ReentrantLock",
        "isHeldByCurrentThread",
        "()Z",
        &[Value::Object(Some(lock))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(held, Value::Int(1));

    let count = call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/locks/ReentrantLock",
        "getHoldCount",
        "()I",
        &[Value::Object(Some(lock))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(count, Value::Int(1));

    // Unlock
    call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/locks/ReentrantLock",
        "unlock",
        "()V",
        &[Value::Object(Some(lock))],
    )
    .unwrap();

    let locked = call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/locks/ReentrantLock",
        "isLocked",
        "()Z",
        &[Value::Object(Some(lock))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(locked, Value::Int(0));
}

