#[test]
fn zoned_date_time_of_and_getters() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");
    // Create a ZoneId
    let zone_str = create_java_string(&shared, "Europe/Paris");
    let zone = call_native(
        &shared,
        &mut thread,
        "java/time/ZoneId",
        "of",
        "(Ljava/lang/String;)Ljava/time/ZoneId;",
        &[Value::Object(Some(zone_str))],
    )
    .unwrap()
    .unwrap();
    // Create LDT
    let ldt = call_native(
        &shared,
        &mut thread,
        "java/time/LocalDateTime",
        "of",
        "(IIIII)Ljava/time/LocalDateTime;",
        &[
            Value::Int(2024),
            Value::Int(7),
            Value::Int(4),
            Value::Int(12),
            Value::Int(0),
        ],
    )
    .unwrap()
    .unwrap();
    // Create ZDT
    let zdt = call_native(
        &shared,
        &mut thread,
        "java/time/ZonedDateTime",
        "of",
        "(Ljava/time/LocalDateTime;Ljava/time/ZoneId;)Ljava/time/ZonedDateTime;",
        &[ldt, zone],
    )
    .unwrap()
    .unwrap();
    if let Value::Object(Some(obj)) = zdt {
        let y = call_native(
            &shared,
            &mut thread,
            "java/time/ZonedDateTime",
            "getYear",
            "()I",
            &[Value::Object(Some(obj))],
        )
        .unwrap()
        .unwrap();
        assert_eq!(y, Value::Int(2024));
        let z = call_native(
            &shared,
            &mut thread,
            "java/time/ZonedDateTime",
            "getZone",
            "()Ljava/time/ZoneId;",
            &[Value::Object(Some(obj))],
        )
        .unwrap()
        .unwrap();
        if let Value::Object(Some(zr)) = z {
            let id = call_native(
                &shared,
                &mut thread,
                "java/time/ZoneId",
                "getId",
                "()Ljava/lang/String;",
                &[Value::Object(Some(zr))],
            )
            .unwrap()
            .unwrap();
            if let Value::Object(Some(s)) = id {
                assert_eq!(
                    read_java_string(&shared.mem.heap, s).unwrap(),
                    "Europe/Paris"
                );
            } else {
                panic!("expected string");
            }
        } else {
            panic!("expected zone");
        }
    } else {
        panic!("expected ZDT");
    }
}

