#[test]
fn thread_local_init_get_set_remove() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");
    let tl = alloc_receiver(&shared, &mut thread, "java/lang/ThreadLocal", 1);
    call_native(
        &shared,
        &mut thread,
        "java/lang/ThreadLocal",
        "<init>",
        "()V",
        &[Value::Object(Some(tl))],
    )
    .unwrap();
    // get returns null initially
    let val = call_native(
        &shared,
        &mut thread,
        "java/lang/ThreadLocal",
        "get",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(tl))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(val, Value::Object(None));
    // set a value
    let s = {
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        ctx.create_string("hello")
    };
    call_native(
        &shared,
        &mut thread,
        "java/lang/ThreadLocal",
        "set",
        "(Ljava/lang/Object;)V",
        &[Value::Object(Some(tl)), Value::Object(Some(s))],
    )
    .unwrap();
    assert_eq!(shared.natives.jni_global_refs.lock().count(), 1);
    // get returns the value
    let val = call_native(
        &shared,
        &mut thread,
        "java/lang/ThreadLocal",
        "get",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(tl))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(val, Value::Object(Some(s)));
    // replacing an object-valued ThreadLocal drops the old root
    let s2 = {
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        ctx.create_string("world")
    };
    call_native(
        &shared,
        &mut thread,
        "java/lang/ThreadLocal",
        "set",
        "(Ljava/lang/Object;)V",
        &[Value::Object(Some(tl)), Value::Object(Some(s2))],
    )
    .unwrap();
    assert_eq!(shared.natives.jni_global_refs.lock().count(), 1);
    let val = call_native(
        &shared,
        &mut thread,
        "java/lang/ThreadLocal",
        "get",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(tl))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(val, Value::Object(Some(s2)));
    // remove clears it
    call_native(
        &shared,
        &mut thread,
        "java/lang/ThreadLocal",
        "remove",
        "()V",
        &[Value::Object(Some(tl))],
    )
    .unwrap();
    assert_eq!(shared.natives.jni_global_refs.lock().count(), 0);
    let val = call_native(
        &shared,
        &mut thread,
        "java/lang/ThreadLocal",
        "get",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(tl))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(val, Value::Object(None));
    assert_eq!(shared.natives.jni_global_refs.lock().count(), 0);
}

#[test]
fn string_tokenizer_basic_tokens() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");
    let st = shared.mem.heap.alloc_object(ClassId::new(0), 3);
    let input = {
        let mut ctx = NativeContextImpl {
            shared: &shared,
            thread: &mut thread,
        };
        ctx.create_string("hello world foo")
    };
    call_native(
        &shared,
        &mut thread,
        "java/util/StringTokenizer",
        "<init>",
        "(Ljava/lang/String;)V",
        &[Value::Object(Some(st)), Value::Object(Some(input))],
    )
    .unwrap();
    // countTokens = 3
    let count = call_native(
        &shared,
        &mut thread,
        "java/util/StringTokenizer",
        "countTokens",
        "()I",
        &[Value::Object(Some(st))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(count, Value::Int(3));
    // hasMoreTokens
    let has = call_native(
        &shared,
        &mut thread,
        "java/util/StringTokenizer",
        "hasMoreTokens",
        "()Z",
        &[Value::Object(Some(st))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(has, Value::Int(1));
    // nextToken
    let t1 = call_native(
        &shared,
        &mut thread,
        "java/util/StringTokenizer",
        "nextToken",
        "()Ljava/lang/String;",
        &[Value::Object(Some(st))],
    )
    .unwrap()
    .unwrap();
    let t1_obj = match t1 {
        Value::Object(Some(o)) => o,
        _ => panic!("expected string"),
    };
    assert_eq!(
        read_java_string(&shared.mem.heap, t1_obj),
        Some("hello".to_string())
    );
    // nextToken again
    let t2 = call_native(
        &shared,
        &mut thread,
        "java/util/StringTokenizer",
        "nextToken",
        "()Ljava/lang/String;",
        &[Value::Object(Some(st))],
    )
    .unwrap()
    .unwrap();
    let t2_obj = match t2 {
        Value::Object(Some(o)) => o,
        _ => panic!("expected string"),
    };
    assert_eq!(
        read_java_string(&shared.mem.heap, t2_obj),
        Some("world".to_string())
    );
    // nextToken 3rd
    let t3 = call_native(
        &shared,
        &mut thread,
        "java/util/StringTokenizer",
        "nextToken",
        "()Ljava/lang/String;",
        &[Value::Object(Some(st))],
    )
    .unwrap()
    .unwrap();
    let t3_obj = match t3 {
        Value::Object(Some(o)) => o,
        _ => panic!("expected string"),
    };
    assert_eq!(
        read_java_string(&shared.mem.heap, t3_obj),
        Some("foo".to_string())
    );
    // hasMoreTokens = false
    let has = call_native(
        &shared,
        &mut thread,
        "java/util/StringTokenizer",
        "hasMoreTokens",
        "()Z",
        &[Value::Object(Some(st))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(has, Value::Int(0));
}

