#[test]
fn synchronous_queue_put_take_p58() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = crate::threading::JvmThread::new(crate::threading::ThreadId(0), "test");
    let sq = shared.mem.heap.alloc_object(ClassId::new(0), 2);
    call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/SynchronousQueue",
        "<init>",
        "()V",
        &[Value::Object(Some(sq))],
    )
    .unwrap();
    // Size should be 0
    let sz = call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/SynchronousQueue",
        "size",
        "()I",
        &[Value::Object(Some(sq))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(sz, Value::Int(0));
    // Put an item
    call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/SynchronousQueue",
        "put",
        "(Ljava/lang/Object;)V",
        &[Value::Object(Some(sq)), Value::Int(42)],
    )
    .unwrap();
    // Take the item
    let taken = call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/SynchronousQueue",
        "take",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(sq))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(taken, Value::Int(42));
    // After take, poll should return null (empty)
    let polled = call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/SynchronousQueue",
        "poll",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(sq))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(polled, Value::Object(None));
}

