#[test]
fn char_buffer_allocate_put_get_p62() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = crate::threading::JvmThread::new(crate::threading::ThreadId(0), "test");
    let buf = call_native(
        &shared,
        &mut thread,
        "java/nio/CharBuffer",
        "allocate",
        "(I)Ljava/nio/CharBuffer;",
        &[Value::Int(10)],
    )
    .unwrap()
    .unwrap();
    let buf_ref = buf.as_object().unwrap();
    let cap = call_native(
        &shared,
        &mut thread,
        "java/nio/CharBuffer",
        "capacity",
        "()I",
        &[Value::Object(Some(buf_ref))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(cap, Value::Int(10));
    // Put 'A'
    call_native(
        &shared,
        &mut thread,
        "java/nio/CharBuffer",
        "put",
        "(C)Ljava/nio/CharBuffer;",
        &[Value::Object(Some(buf_ref)), Value::Int('A' as i32)],
    )
    .unwrap();
    // Put 'B'
    call_native(
        &shared,
        &mut thread,
        "java/nio/CharBuffer",
        "put",
        "(C)Ljava/nio/CharBuffer;",
        &[Value::Object(Some(buf_ref)), Value::Int('B' as i32)],
    )
    .unwrap();
    // Flip
    call_native(
        &shared,
        &mut thread,
        "java/nio/CharBuffer",
        "flip",
        "()Ljava/nio/CharBuffer;",
        &[Value::Object(Some(buf_ref))],
    )
    .unwrap();
    // remaining should be 2
    let rem = call_native(
        &shared,
        &mut thread,
        "java/nio/CharBuffer",
        "remaining",
        "()I",
        &[Value::Object(Some(buf_ref))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(rem, Value::Int(2));
    // Get first char
    let ch1 = call_native(
        &shared,
        &mut thread,
        "java/nio/CharBuffer",
        "get",
        "()C",
        &[Value::Object(Some(buf_ref))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(ch1, Value::Int('A' as i32));
    let ch2 = call_native(
        &shared,
        &mut thread,
        "java/nio/CharBuffer",
        "get",
        "()C",
        &[Value::Object(Some(buf_ref))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(ch2, Value::Int('B' as i32));
}

