#[test]
fn stamped_lock_read_write_p62() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = crate::threading::JvmThread::new(crate::threading::ThreadId(0), "test");
    let lock = shared.mem.heap.alloc_object(ClassId::new(0), 2);
    call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/locks/StampedLock",
        "<init>",
        "()V",
        &[Value::Object(Some(lock))],
    )
    .unwrap();
    // Read lock
    let stamp = call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/locks/StampedLock",
        "readLock",
        "()J",
        &[Value::Object(Some(lock))],
    )
    .unwrap()
    .unwrap();
    assert!(matches!(stamp, Value::Long(s) if s > 0));
    // isReadLocked
    let rl = call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/locks/StampedLock",
        "isReadLocked",
        "()Z",
        &[Value::Object(Some(lock))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(rl, Value::Int(1));
    // Unlock read
    call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/locks/StampedLock",
        "unlockRead",
        "(J)V",
        &[Value::Object(Some(lock)), stamp],
    )
    .unwrap();
    // Write lock
    let ws = call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/locks/StampedLock",
        "writeLock",
        "()J",
        &[Value::Object(Some(lock))],
    )
    .unwrap()
    .unwrap();
    assert!(matches!(ws, Value::Long(s) if s != 0));
    let wl = call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/locks/StampedLock",
        "isWriteLocked",
        "()Z",
        &[Value::Object(Some(lock))],
    )
    .unwrap()
    .unwrap();
    assert_eq!(wl, Value::Int(1));
    // Unlock write
    call_native(
        &shared,
        &mut thread,
        "java/util/concurrent/locks/StampedLock",
        "unlockWrite",
        "(J)V",
        &[Value::Object(Some(lock)), ws],
    )
    .unwrap();
}

