#[test]
fn collator_basics_p66() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");
    let c = "java/text/Collator";

    // getInstance
    let coll = call_native(
        &shared,
        &mut thread,
        c,
        "getInstance",
        "()Ljava/text/Collator;",
        &[],
    )
    .unwrap()
    .unwrap();
    assert!(matches!(coll, Value::Object(Some(_))));

    if let Value::Object(Some(obj)) = coll {
        // Default strength is SECONDARY (2)
        let s = call_native(
            &shared,
            &mut thread,
            c,
            "getStrength",
            "()I",
            &[Value::Object(Some(obj))],
        )
        .unwrap()
        .unwrap();
        assert_eq!(s, Value::Int(2));

        // setStrength
        call_native(
            &shared,
            &mut thread,
            c,
            "setStrength",
            "(I)V",
            &[Value::Object(Some(obj)), Value::Int(0)],
        )
        .unwrap();
        let s2 = call_native(
            &shared,
            &mut thread,
            c,
            "getStrength",
            "()I",
            &[Value::Object(Some(obj))],
        )
        .unwrap()
        .unwrap();
        assert_eq!(s2, Value::Int(0));

        // compare
        let a = create_java_string(&shared, "apple");
        let b = create_java_string(&shared, "banana");
        let cmp = call_native(
            &shared,
            &mut thread,
            c,
            "compare",
            "(Ljava/lang/String;Ljava/lang/String;)I",
            &[
                Value::Object(Some(obj)),
                Value::Object(Some(a)),
                Value::Object(Some(b)),
            ],
        )
        .unwrap()
        .unwrap();
        assert_eq!(cmp, Value::Int(-1));

        // equals
        let eq = call_native(
            &shared,
            &mut thread,
            c,
            "equals",
            "(Ljava/lang/String;Ljava/lang/String;)Z",
            &[
                Value::Object(Some(obj)),
                Value::Object(Some(a)),
                Value::Object(Some(a)),
            ],
        )
        .unwrap()
        .unwrap();
        assert_eq!(eq, Value::Int(1));
    }
}

