#[test]
fn integer_unsigned_ops_p71() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    // signum
    assert_eq!(
        call_native(
            &shared,
            &mut thread,
            "java/lang/Integer",
            "signum",
            "(I)I",
            &[Value::Int(-5)]
        )
        .unwrap()
        .unwrap(),
        Value::Int(-1)
    );
    assert_eq!(
        call_native(
            &shared,
            &mut thread,
            "java/lang/Integer",
            "signum",
            "(I)I",
            &[Value::Int(0)]
        )
        .unwrap()
        .unwrap(),
        Value::Int(0)
    );
    assert_eq!(
        call_native(
            &shared,
            &mut thread,
            "java/lang/Integer",
            "signum",
            "(I)I",
            &[Value::Int(7)]
        )
        .unwrap()
        .unwrap(),
        Value::Int(1)
    );

    // highestOneBit
    assert_eq!(
        call_native(
            &shared,
            &mut thread,
            "java/lang/Integer",
            "highestOneBit",
            "(I)I",
            &[Value::Int(10)]
        )
        .unwrap()
        .unwrap(),
        Value::Int(8)
    );

    // lowestOneBit
    assert_eq!(
        call_native(
            &shared,
            &mut thread,
            "java/lang/Integer",
            "lowestOneBit",
            "(I)I",
            &[Value::Int(12)]
        )
        .unwrap()
        .unwrap(),
        Value::Int(4)
    );

    // rotateLeft
    assert_eq!(
        call_native(
            &shared,
            &mut thread,
            "java/lang/Integer",
            "rotateLeft",
            "(II)I",
            &[Value::Int(1), Value::Int(3)]
        )
        .unwrap()
        .unwrap(),
        Value::Int(8)
    );

    // compareUnsigned: -1 as unsigned > any positive
    let cmp = call_native(
        &shared,
        &mut thread,
        "java/lang/Integer",
        "compareUnsigned",
        "(II)I",
        &[Value::Int(-1), Value::Int(1)],
    )
    .unwrap()
    .unwrap();
    assert_eq!(cmp, Value::Int(1));
}

