    let entry2 = match le {
        Some(Value::Object(Some(o))) => o,
        _ => panic!("expected entry"),
    };
    let val2 = call_native(
        &shared,
        &mut thread,
        "java/util/Map$Entry",
        "getValue",
        "()Ljava/lang/Object;",
        &[Value::Object(Some(entry2))],
    )
    .unwrap();
    assert_eq!(unbox_int(&shared, &mut thread, val2), Some(Value::Int(3)));
