#[test]
fn collections_rotate_test() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");

    let list = shared.mem.heap.alloc_object(ClassId::new(0), 2);
    call_native(
        &shared,
        &mut thread,
        "java/util/ArrayList",
        "<init>",
        "()V",
        &[Value::Object(Some(list))],
    )
    .unwrap();

    // [10, 20, 30]
    for v in [10, 20, 30] {
        call_native(
            &shared,
            &mut thread,
            "java/util/ArrayList",
            "add",
            "(Ljava/lang/Object;)Z",
            &[Value::Object(Some(list)), Value::Int(v)],
        )
        .unwrap();
    }

    // Rotate by 1: [10,20,30] → [30,10,20]
    call_native(
        &shared,
        &mut thread,
        "java/util/Collections",
        "rotate",
        "(Ljava/util/List;I)V",
        &[Value::Object(Some(list)), Value::Int(1)],
    )
    .unwrap();

    let r0 = call_native(
        &shared,
        &mut thread,
        "java/util/ArrayList",
        "get",
        "(I)Ljava/lang/Object;",
        &[Value::Object(Some(list)), Value::Int(0)],
    )
    .unwrap();
    assert_eq!(r0, Some(Value::Int(30)));

    let r1 = call_native(
        &shared,
        &mut thread,
        "java/util/ArrayList",
        "get",
        "(I)Ljava/lang/Object;",
        &[Value::Object(Some(list)), Value::Int(1)],
    )
    .unwrap();
    assert_eq!(r1, Some(Value::Int(10)));

    let r2 = call_native(
        &shared,
        &mut thread,
        "java/util/ArrayList",
        "get",
        "(I)Ljava/lang/Object;",
        &[Value::Object(Some(list)), Value::Int(2)],
    )
    .unwrap();
    assert_eq!(r2, Some(Value::Int(20)));
}

