// =====================================================================
// M22 — RSA/ECDSA signing end-to-end
// =====================================================================

/// Helper: generate a key pair for the given algorithm via native calls.
/// Returns (KeyPair object, PublicKey object, PrivateKey object).
fn m22_generate_keypair(
    shared: &Arc<SharedVm>,
    thread: &mut JvmThread,
    algorithm: &str,
    key_size: i32,
) -> (ObjectRef, ObjectRef, ObjectRef) {
    // KeyPairGenerator.getInstance(algorithm)
    let alg_str = crate::vm::vm_object::create_java_string(shared, algorithm);
    let kpg = call_native(
        shared,
        thread,
        "java/security/KeyPairGenerator",
        "getInstance",
        "(Ljava/lang/String;)Ljava/security/KeyPairGenerator;",
        &[Value::Object(Some(alg_str))],
    )
    .unwrap()
    .unwrap();
    let kpg_ref = match kpg {
        Value::Object(Some(r)) => r,
        _ => panic!("M22: expected KPG object"),
    };

    // initialize(keySize)
    call_native(
        shared,
        thread,
        "java/security/KeyPairGenerator",
        "initialize",
        "(I)V",
        &[Value::Object(Some(kpg_ref)), Value::Int(key_size)],
    )
    .unwrap();

    // generateKeyPair()
    let kp = call_native(
        shared,
        thread,
        "java/security/KeyPairGenerator",
        "generateKeyPair",
        "()Ljava/security/KeyPair;",
        &[Value::Object(Some(kpg_ref))],
    )
    .unwrap()
    .unwrap();
    let kp_ref = match kp {
        Value::Object(Some(r)) => r,
        _ => panic!("M22: expected KeyPair"),
    };

    // getPublic() / getPrivate()
    let pub_val = call_native(
        shared,
        thread,
        "java/security/KeyPair",
        "getPublic",
        "()Ljava/security/PublicKey;",
        &[Value::Object(Some(kp_ref))],
    )
    .unwrap()
    .unwrap();
    let pub_ref = match pub_val {
        Value::Object(Some(r)) => r,
        _ => panic!("M22: expected PublicKey"),
    };

    let priv_val = call_native(
        shared,
        thread,
        "java/security/KeyPair",
        "getPrivate",
        "()Ljava/security/PrivateKey;",
        &[Value::Object(Some(kp_ref))],
    )
    .unwrap()
    .unwrap();
    let priv_ref = match priv_val {
        Value::Object(Some(r)) => r,
        _ => panic!("M22: expected PrivateKey"),
    };

    (kp_ref, pub_ref, priv_ref)
}

/// Helper: sign data with the given algorithm and private key.
fn m22_sign(
    shared: &Arc<SharedVm>,
    thread: &mut JvmThread,
    sig_algorithm: &str,
    private_key: ObjectRef,
    data: &[u8],
) -> ObjectRef {
    let alg_str = crate::vm::vm_object::create_java_string(shared, sig_algorithm);
    let sig = call_native(
        shared,
        thread,
        "java/security/Signature",
        "getInstance",
        "(Ljava/lang/String;)Ljava/security/Signature;",
        &[Value::Object(Some(alg_str))],
    )
    .unwrap()
    .unwrap();
    let sig_ref = match sig {
        Value::Object(Some(r)) => r,
        _ => panic!("M22: expected Signature"),
    };

    // initSign(privateKey)
    call_native(
        shared,
        thread,
        "java/security/Signature",
        "initSign",
        "(Ljava/security/PrivateKey;)V",
        &[
            Value::Object(Some(sig_ref)),
            Value::Object(Some(private_key)),
        ],
    )
    .unwrap();

    // update(byte[])
    let arr = shared.mem.heap.alloc_array(
        ClassId::new(0),
        crate::memory::heap::ArrayElementType::Byte,
        data.len(),
    );
    for (i, &b) in data.iter().enumerate() {
        let _ = shared
            .mem
            .heap
            .set_array_element(arr, i, Value::Int(b as i8 as i32));
    }
    call_native(
        shared,
        thread,
        "java/security/Signature",
        "update",
        "([B)V",
        &[Value::Object(Some(sig_ref)), Value::Object(Some(arr))],
    )
    .unwrap();

    // sign() -> byte[]
    let sig_bytes = call_native(
        shared,
        thread,
        "java/security/Signature",
        "sign",
        "()[B",
        &[Value::Object(Some(sig_ref))],
    )
    .unwrap()
    .unwrap();
    match sig_bytes {
        Value::Object(Some(r)) => r,
        _ => panic!("M22: expected signature byte[]"),
    }
}

/// Helper: verify signature.
fn m22_verify(
    shared: &Arc<SharedVm>,
    thread: &mut JvmThread,
    sig_algorithm: &str,
    public_key: ObjectRef,
    data: &[u8],
    signature: ObjectRef,
) -> bool {
    let alg_str = crate::vm::vm_object::create_java_string(shared, sig_algorithm);
    let sig = call_native(
        shared,
        thread,
        "java/security/Signature",
        "getInstance",
        "(Ljava/lang/String;)Ljava/security/Signature;",
        &[Value::Object(Some(alg_str))],
    )
    .unwrap()
    .unwrap();
    let sig_ref = match sig {
        Value::Object(Some(r)) => r,
        _ => panic!("M22: expected Signature"),
    };

    // initVerify(publicKey)
    call_native(
        shared,
        thread,
        "java/security/Signature",
        "initVerify",
        "(Ljava/security/PublicKey;)V",
        &[
            Value::Object(Some(sig_ref)),
            Value::Object(Some(public_key)),
        ],
    )
    .unwrap();

    // update(byte[])
    let arr = shared.mem.heap.alloc_array(
        ClassId::new(0),
        crate::memory::heap::ArrayElementType::Byte,
        data.len(),
    );
    for (i, &b) in data.iter().enumerate() {
        let _ = shared
            .mem
            .heap
            .set_array_element(arr, i, Value::Int(b as i8 as i32));
    }
    call_native(
        shared,
        thread,
        "java/security/Signature",
        "update",
        "([B)V",
        &[Value::Object(Some(sig_ref)), Value::Object(Some(arr))],
    )
    .unwrap();

    // verify(byte[]) -> boolean
    let result = call_native(
        shared,
        thread,
        "java/security/Signature",
        "verify",
        "([B)Z",
        &[Value::Object(Some(sig_ref)), Value::Object(Some(signature))],
    )
    .unwrap()
    .unwrap();
    match result {
        Value::Int(v) => v != 0,
        _ => false,
    }
}

#[test]
fn m22_rsa_keygen() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");
    let (_kp, pub_key, priv_key) = m22_generate_keypair(&shared, &mut thread, "RSA", 512);
    // PublicKey field 0 = alg_idx (6=RSA), field 1 = key_size
    let alg = shared.mem.heap.get_field(pub_key, 0);
    assert_eq!(alg, Value::Int(6), "M22: RSA alg index should be 6");
    let size = shared.mem.heap.get_field(pub_key, 1);
    assert_eq!(size, Value::Int(512), "M22: RSA key size should be 512");
    let priv_alg = shared.mem.heap.get_field(priv_key, 0);
    assert_eq!(priv_alg, Value::Int(6));
}

#[test]
fn m22_rsa_sign_verify_roundtrip() {
    let shared = Arc::new(SharedVm::new(VmConfig::default()));
    let mut thread = JvmThread::new(ThreadId(0), "test");
    let (_kp, pub_key, priv_key) = m22_generate_keypair(&shared, &mut thread, "RSA", 512);
    let data = b"Hello, RSA signing!";
    let signature = m22_sign(&shared, &mut thread, "SHA256withRSA", priv_key, data);
    let sig_len = shared.mem.heap.array_length(signature);
    assert!(sig_len > 0, "M22: RSA signature should be non-empty");
    let valid = m22_verify(
        &shared,
        &mut thread,
        "SHA256withRSA",
        pub_key,
        data,
        signature,
    );
    assert!(valid, "M22: RSA signature should verify");
}

